void screen_idle1_time_update(lv_obj_t * ui_Screenidle1)
{
    uint8_t         nongli_month[2] = {
        0
        };
    ui_screenidle1_obj_t * p_screen_param;
    uint8_t         buf[20],i;
    aos_systime     cur_time = {
        0
        };
    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screenidle1);

    aos_get_systime(&cur_time);
    i                   = 0;
    buf[i++]            = cur_time.hour / 10;
    buf[i++]            = cur_time.hour % 10;
    buf[i++]            = 10;
    buf[i++]            = cur_time.minute / 10;
    buf[i++]            = cur_time.minute % 10;
    img_label_set_text(p_screen_param->img_label[OBJ_NUM_HOUR_MIN],buf,i);

    i                   = 0;
    buf[i++]            = cur_time.year / 1000;
    buf[i++]            = cur_time.year % 1000 / 100;
    buf[i++]            = cur_time.year % 1000 % 100 / 10;
    buf[i++]            = cur_time.year % 1000 % 100 % 10;

    buf[i++]            = 10;

    buf[i++]            = cur_time.month / 10;
    buf[i++]            = cur_time.month % 10;

    buf[i++]            = 10;

    buf[i++]            = cur_time.day / 10;
    buf[i++]            = cur_time.day % 10;
    img_label_set_text(p_screen_param->img_label[OBJ_NUM_YEAR_MON_DAY],buf,i);

#ifdef CONFIG_APP_TOOLS_FP
    nongli_num(cur_time.year,cur_time.month,cur_time.day,nongli_month);

    lv_img_set_src(p_screen_param->obj_img[OBJ_IMG_WEEK],ui_imgset_week[cur_time.wday]);


    i                   = 0;
    buf[i++]            = nongli_month[1] -1;
    buf[i++]            = 12;
    img_label_set_text(p_screen_param->img_label[OBJ_NUM_MONTH],buf,i);
#endif

    i                   = 0;

    //buf[i++] = 10+(nongli_month[0]-1)/10;
    if (nongli_month[0] <= 10) {
        buf[i++]            = 10;
        buf[i++]            = (nongli_month[0] -1) % 10;
        }
    else if (nongli_month[0] < 20) {
        buf[i++]            = 11;
        buf[i++]            = (nongli_month[0] -1) % 10;
        }
    else if (nongli_month[0] == 20) {
        buf[i++]            = 2 - 1;
        buf[i++]            = 10 - 1;
        }
    else if (nongli_month[0] == 30) {
        buf[i++]            = 3 - 1;
        buf[i++]            = 10 - 1;

        }
    else {
        buf[i++]            = 12;
        buf[i++]            = (nongli_month[0] -1) % 10;
        }

    img_label_set_text(p_screen_param->img_label[OBJ_NUM_DAY],buf,i);

}


const lv_img_dsc_t * screen_idle1_get_radio_signal()
{
    uint8_t         signal_type,signal_lev;

    if((false==get_is_sim_inited_status())||false==get_is_sim_exist_status()){	
        __inf("screen_idle1_get_radio_signal");
        return ui_imgset_signal_null[0];
    }
    //p_screen_param->img_label[OBJ_IMG_SIGNAL] =
    //if(settings_flow_get_flightmode_status()){
    if(is_set_net_flight_flash()){
        __inf("screen_idle1_get_radio_signal1");
        return ui_imgset_signal_null[2];
    }
    signal_type = get_radio_signal_type();
    signal_lev	= get_radio_signal_lev();
    lv_img_dsc_t **img_radio_signal;

    __inf("screen_idle1_get_radio_signal:%d,%d",signal_type,signal_lev);

    switch (signal_type)
    {
        case TS_RADIO_NETWORK_TYPE_UNKNOWN:
            return ui_imgset_signal_null[0];

            /* GSM: Global System For Mobile Communication */
        case TS_RADIO_NETWORK_TYPE_GSM:
            img_radio_signal = (lv_img_dsc_t * *) ui_imgset_signal_2g;
            break;

        /* CDMA: Code Division Multiple Access */
        case TS_RADIO_NETWORK_TYPE_CDMA:
            img_radio_signal = (lv_img_dsc_t * *) ui_imgset_signal_2g;
            break;

        /* WCDMA: Wideband Code Division Multiple Access */
        case TS_RADIO_NETWORK_TYPE_WCDMA:
            img_radio_signal = (lv_img_dsc_t * *) ui_imgset_signal_3g;
            break;

        /* TDSCDMA: TimeDivision-Synchronous Code Division Multiple Access */
        case TS_RADIO_NETWORK_TYPE_TDSCDMA:
            img_radio_signal = (lv_img_dsc_t * *) ui_imgset_signal_3g;
            break;

        /* LTE: Long Term Evolution */
        case TS_RADIO_NETWORK_TYPE_LTE:
            img_radio_signal = (lv_img_dsc_t * *) ui_imgset_signal_4g;
            break;

        /* 5G NR: New Radio */
        case TS_RADIO_NETWORK_TYPE_NR:
            img_radio_signal = (lv_img_dsc_t * *) ui_imgset_signal_4g;
            break;

        default:
            img_radio_signal = (lv_img_dsc_t * *)ui_imgset_signal_null;
            break;
        }

    if (signal_lev < 5) {
        return img_radio_signal[signal_lev];
        }

    return ui_imgset_signal_null[0];

}


void screen_idle1_status_radio_func_callback(uint32_t radio_type,void * user_data)
{
    lv_obj_t *      ui_Screenidle1;
    ui_screenidle1_obj_t * p_screen_param;

    ui_Screenidle1      = user_data;
    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screenidle1);


    switch (radio_type)
    {
        case TS_EVENT_RADIO_SIGNAL_INFO_UPDATED:
            {
                lv_img_dsc_t *  img_dsc;

                img_dsc             = (lv_img_dsc_t *) screen_idle1_get_radio_signal();

                lv_img_set_src(p_screen_param->obj_img[OBJ_IMG_SIGNAL],img_dsc);
                break;
                }

        case TS_EVENT_RADIO_IMS_REG_STATUS_UPDATED:
            {
                lv_img_dsc_t *img_dsc;
                img_dsc = (lv_img_dsc_t *)screen_idle1_get_radio_signal();

                lv_img_set_src(p_screen_param->obj_img[OBJ_IMG_SIGNAL], img_dsc);
                break;
                }

        case TS_EVENT_RADIO_OPERATOR_INFO_UPDATED:
            {
                char *          opterators;

                if(is_set_net_flight_flash()){
                    opterators = "飞行模式";
                }else{
                    opterators = get_radio_operator_name();
                }

                if (opterators != NULL) {
                    if (p_screen_param->obj_label[OBJ_LABEL_OPERATORS] == NULL) {
                        p_screen_param->obj_label[OBJ_LABEL_OPERATORS] = lv_label_create(ui_Screenidle1);

                        lv_obj_set_x(p_screen_param->obj_label[OBJ_LABEL_OPERATORS],
                            obj_batch_label_param_array[OBJ_LABEL_OPERATORS].x);
                        lv_obj_set_y(p_screen_param->obj_label[OBJ_LABEL_OPERATORS],
                            obj_batch_label_param_array[OBJ_LABEL_OPERATORS].y);
                        lv_obj_set_width(p_screen_param->obj_label[OBJ_LABEL_OPERATORS],
                            obj_batch_label_param_array[OBJ_LABEL_OPERATORS].witdh); /// 1
                        lv_obj_set_height(p_screen_param->obj_label[OBJ_LABEL_OPERATORS],
                            obj_batch_label_param_array[OBJ_LABEL_OPERATORS].high); /// 1
                        lv_obj_set_align(p_screen_param->obj_label[OBJ_LABEL_OPERATORS],
                            obj_batch_label_param_array[OBJ_LABEL_OPERATORS].align);
                        lv_obj_set_style_text_color(p_screen_param->obj_label[OBJ_LABEL_OPERATORS],
                            lv_color_hex(0xffffff),LV_PART_MAIN | LV_STATE_DEFAULT);

                        }

                    lv_label_set_text(p_screen_param->obj_label[OBJ_LABEL_OPERATORS],opterators);
                    }
                }
            break;
        }
}


