void screen_idle1_status_bat_func_callback(void * user_data)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(user_data);

    if (1 == get_bat_chg_status()) {
        screen_idle1_bat_timer_start(user_data);

        }
    else {
        uint8_t         bat_capacity = get_bat_capacity();

        screen_idle1_bat_timer_stop(user_data);

        bat_capacity        = (bat_capacity + 5) / 10;

        lv_img_set_src(p_screen_param->obj_img[OBJ_IMG_BAT],ui_imgset_bat[bat_capacity]);
        }
}


