static void lv_obj_del_screen_ready_cb(lv_anim_t * a)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(a->var);

    status_radio_set_func_callback(NULL,NULL);
    status_bat_set_func_callback(NULL,NULL);

    screen_idle1_bat_timer_stop(a->var);

    screen_idle1_timer_stop(a->var);

    img_label_destroy(p_screen_param->img_label[OBJ_NUM_HOUR_MIN]);
    img_label_destroy(p_screen_param->img_label[OBJ_NUM_YEAR_MON_DAY]);

    lv_mem_free(p_screen_param);
    lv_obj_set_user_data(a->var,NULL);
    lv_obj_del(a->var);

}


void ui_Screenidle1_screen_uninit(lv_obj_t * win,void * p)
{
    lv_obj_t *      ui_Screenidle1;

    ui_Screenidle1      = lv_obj_get_user_data(win);

    if (ui_Screenidle1) {
        lv_obj_del_delayed_callback(ui_Screenidle1,100,lv_obj_del_screen_ready_cb);
        }

    lv_obj_set_user_data(win,NULL);
}


void screen_idle1_timer_stop(lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer != NULL) {
        lv_timer_del(p_screen_param->handle_timer);
        p_screen_param->handle_timer = NULL;
        }


}



void screen_idle1_timer_pause(lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer != NULL) {
        lv_timer_pause(p_screen_param->handle_timer);
        }

}


void screen_idle1_timer_resume(lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer != NULL) {
        lv_timer_resume(p_screen_param->handle_timer);
        }


}



static void screen_idle1_timer_event_cb(struct _lv_timer_t *timer)
{
    lv_obj_t *      ui_Screen;
    ui_screenidle1_obj_t * p_screen_param;

    ui_Screen           = timer->user_data;
    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);


    screen_idle1_time_update(ui_Screen);

    if (app_musicplayer_get_play_status()) {
        uint8_t *       title = (uint8_t *) app_musicplayer_get_cur_title();

        if (strcmp(title,lv_label_get_text(p_screen_param->obj_music_title)))
            lv_label_set_text(p_screen_param->obj_music_title,(const char *) app_musicplayer_get_cur_title());

        lv_obj_clear_flag(p_screen_param->obj_music_title,LV_OBJ_FLAG_HIDDEN);

        lv_obj_add_flag(p_screen_param->obj_music_title_tmp,LV_OBJ_FLAG_HIDDEN);
        }
    else {
        lv_obj_clear_flag(p_screen_param->obj_music_title_tmp,LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(p_screen_param->obj_music_title,LV_OBJ_FLAG_HIDDEN);
        }


}


void screen_idle1_timer_start(lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);


    if (p_screen_param->handle_timer == NULL) {
        p_screen_param->handle_timer = lv_timer_create(screen_idle1_timer_event_cb,1000,ui_Screen);
        }

}



void screen_idle1_bat_timer_stop(lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer_bat != NULL) {
        lv_timer_del(p_screen_param->handle_timer_bat);
        p_screen_param->handle_timer_bat = NULL;
        }


}



static void screen_idle1_bat_timer_event_cb(struct _lv_timer_t *timer)
{
    lv_obj_t *      ui_Screen;
    ui_screenidle1_obj_t * p_screen_param;

    ui_Screen           = timer->user_data;
    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->bat_img_count >= 10)
        p_screen_param->bat_img_count = 0;

    lv_img_set_src(p_screen_param->obj_img[OBJ_IMG_BAT],ui_imgset_bat_charge[p_screen_param->bat_img_count]);

    p_screen_param->bat_img_count++;


}


void screen_idle1_bat_timer_start(lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);


    if (p_screen_param->handle_timer_bat == NULL) {
        p_screen_param->bat_img_count = 0;
        p_screen_param->handle_timer_bat = lv_timer_create(screen_idle1_bat_timer_event_cb,200,ui_Screen);
        }

}



void remind_timer_callback_screen_idle1(screen_remind_param_t * p_param)
{
    lv_obj_t *      ui_Screen;

    ui_Screen           = p_param->user_data;

    if (p_param->new_win) {
        alv_am_win_enter(NULL,"idle_lock",NULL);
        alv_am_win_exit_action(NULL,"watch",NULL);
        extern int backlight_turn_off1(void);
        backlight_turn_off1();
        }
    else {
        //lv_obj_invalidate(ui_Screen);
        lv_disp_load_scr(ui_Screen);
        }
}


void screen_idle1_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);

    switch (key)
    {
        case LV_KEY_END:
            {
                extern uint8_t get_power_key_lock_status(void);

                if (get_power_key_lock_status()) {
                    screen_remind_param_t screen_remind_param;
                    lv_obj_t *      ui_screen;

                    ui_screen_remind_param_init(&screen_remind_param);

                    screen_remind_param.str = "键盘已上锁";
                    screen_remind_param.tiemr_delay = 1200;
                    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_screen_idle1;
                    screen_remind_param.user_data = ui_Screen;
                    screen_remind_param.new_win = 1;
                    ui_screen           = ui_screen_remind_init(&screen_remind_param);

                    lv_disp_load_scr(ui_screen);

                    }

                }
            break;
        }
}

void screen_idle1_key_event_state(uint32_t key,uint32_t code,lv_obj_t * ui_Screen)
{
    ui_screenidle1_obj_t * p_screen_param;

    p_screen_param      = (ui_screenidle1_obj_t *) lv_obj_get_user_data(ui_Screen);

    key_update_pressed(key,code);

    if (code == LV_EVENT_PRESSED)
        p_screen_param->key_pressed_in_this_win = 1;

    switch (key)
    {
        case LV_KEY_UP:
            {
                lv_obj_t *      frist_win;
                lv_obj_t *      app;
                uint8_t         enter_param = 0x80;

                if ((code != LV_EVENT_RELEASED) || (0 == key_is_pressed(key)))
                    break;

                app                 = get_app_by_name("tools");
                frist_win           = get_win_by_name(app,"tools_calendar");
                alv_am_app_set_first_win(app,frist_win);
                alv_am_app_enter_action(NULL,"tools",&enter_param);

                }
            break;

        case LV_KEY_DOWN:
            {
                lv_obj_t *      frist_win;
                lv_obj_t *      app;
                uint8_t         enter_param = 0x80;

                if ((code != LV_EVENT_RELEASED) || (0 == key_is_pressed(key)))
                    break;

                app                 = get_app_by_name("tools");
                frist_win           = get_win_by_name(app,"tools_calculator");
                alv_am_app_set_first_win(app,frist_win);
                alv_am_app_enter_action(NULL,"tools",&enter_param);
                }
            break;

        case LV_KEY_LEFT:
            {
                uint8_t         enter_param = 0x80;

                if ((code != LV_EVENT_RELEASED) || (0 == key_is_pressed(key)))
                    break;

                if (0 == sdmmc_get_card_status()) {
                    create_comp_msgbox_remind_play_tts_menu("请插入T卡");
                    }
                else {
                    if (app_music_list_is_empty())
                        create_comp_msgbox_remind_play_tts_menu("T卡无音乐");
                    else 
                        alv_am_app_enter_action(NULL,"multmedia",&enter_param);

                    }

                }
            break;

        case LV_KEY_RIGHT:
            {
                void *          p_enter_param;

                p_enter_param       = (void *) create_app_sms_enter_param_fisrt_write_win(NULL,NULL);
                alv_am_app_enter_action(NULL,"sms",p_enter_param);
                }
            break;

        case LV_KEY_END:
            {
                extern uint8_t get_power_key_lock_status(void);

                if ((code != LV_EVENT_RELEASED) || (0 == key_is_pressed(key)))
                    break;

                if (get_power_key_lock_status()) {
                    screen_remind_param_t screen_remind_param;
                    lv_obj_t *      ui_screen;

                    ui_screen_remind_param_init(&screen_remind_param);

                    screen_remind_param.str = "键盘已上锁";
                    screen_remind_param.tiemr_delay = 1500;
                    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_screen_idle1;
                    screen_remind_param.user_data = ui_Screen;
                    screen_remind_param.new_win = 1;
                    ui_screen           = ui_screen_remind_init(&screen_remind_param);

                    lv_disp_load_scr(ui_screen);

                    }

                }
            break;

        case LV_KEY_HOME:
            {
                void *          p;

                if ((code != LV_EVENT_RELEASED) || (0 == key_is_pressed(key)))
                    break;

                if ((is_calllog_data_missed_calls_empty()) && (is_calllog_data_recevied_calls_empty()) &&
                     (is_calllog_data_dialed_number_empty ())) {
                    calllog_menu_remind_screen(ui_Screen,0);
                    break;
                    }


                p                   = create_app_calllog_enter_param_fisrt_dial_win(3);
                alv_am_app_enter_action(NULL,"calllog",p);
                destory_app_calllog_enter_param(p);
                }
            break;

        case LV_KEY_ENTER:
        case LV_KEY_ESC:
            {
                if ((code != LV_EVENT_RELEASED) || (0 == key_is_pressed(key)))
                    break;

                alv_am_app_enter_action(NULL,"home_fp",NULL);


                }
            break;

        case LV_KEY_DEL:
            {
                if ((code != LV_EVENT_RELEASED) || (0 == key_is_pressed(key)) ||
                     (p_screen_param->key_pressed_in_this_win == 0))
                    break;

                if (phonebook_data_is_init()) {
                    alv_am_app_enter_action(NULL,"phonebook",NULL);
                    }
                else {
                    screen_remind_param_t screen_remind_param;
                    lv_obj_t *      ui_screen;

                    ui_screen_remind_param_init(&screen_remind_param);

                    screen_remind_param.str = "联系人未准备好";
                    screen_remind_param.tiemr_delay = 1500;
                    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_screen_idle1;
                    screen_remind_param.user_data = ui_Screen;
                    screen_remind_param.new_win = 0;

                    ui_screen           = ui_screen_remind_init(&screen_remind_param);

                    lv_disp_load_scr(ui_screen);
                    }

                }
            break;

        case LV_KEY_9:
        case LV_KEY_8:
        case LV_KEY_7:
        case LV_KEY_6:
        case LV_KEY_5:
        case LV_KEY_4:
        case LV_KEY_3:
        case LV_KEY_2:
        case LV_KEY_1:
        case LV_KEY_0:
        case LV_KEY_STAR:
        case LV_KEY_HASH:
            {
                uint32_t        flag;


                flag                = key_get_pressed_flag(key);

                if ((1 << LV_EVENT_LONG_PRESSED_REPEAT) &flag) {

                    key_update_release(key,LV_EVENT_RELEASED);
                    }
                else if ((1 << LV_EVENT_LONG_PRESSED) &flag) {
                    if (key == LV_KEY_HASH) {
                        extern uint8_t set_theme_with_hash(void);

                        if (set_theme_with_hash() == 0) {
                            screen_remind_param_t screen_remind_param;
                            lv_obj_t *      ui_screen;

                            //lv_obj_add_flag( p_screen_param->obj_img[OBJ_IMG_MUTE], LV_OBJ_FLAG_HIDDEN ); /// Flags	
                            ui_screenidle1_create_remind_img(ui_Screen);
                            ui_screen_remind_param_init(&screen_remind_param);

                            screen_remind_param.str = "标准";
                            screen_remind_param.tiemr_delay = 1200;
                            screen_remind_param.fun =
                                 (remind_timer_callback_fun_t) remind_timer_callback_screen_idle1;
                            screen_remind_param.user_data = ui_Screen;

                            screen_remind_param.new_win = 0;
                            ui_screen           = ui_screen_remind_init(&screen_remind_param);
                            lv_disp_load_scr(ui_screen);
                            }
                        else {
                            screen_remind_param_t screen_remind_param;
                            lv_obj_t *      ui_screen;

                            //lv_obj_clear_flag( p_screen_param->obj_img[OBJ_IMG_MUTE], LV_OBJ_FLAG_HIDDEN ); /// Flags							
                            ui_screenidle1_create_remind_img(ui_Screen);
                            ui_screen_remind_param_init(&screen_remind_param);

                            screen_remind_param.str = "静音";
                            screen_remind_param.tiemr_delay = 1200;
                            screen_remind_param.fun =
                                 (remind_timer_callback_fun_t) remind_timer_callback_screen_idle1;
                            screen_remind_param.user_data = ui_Screen;

                            screen_remind_param.new_win = 0;
                            ui_screen           = ui_screen_remind_init(&screen_remind_param);
                            lv_disp_load_scr(ui_screen);
                            }
                        }
                    else if (key == LV_KEY_0) {
                        aos_systime     cur_time = {
                            0
                            };
                        uint8_t         str_buf[50];

                        memset(str_buf,0,50);
                        aos_get_systime(&cur_time);
                        sprintf(str_buf,"现在是北京时间%02d:%02d",cur_time.hour,cur_time.minute);
                        app_fp_play_tts_once_time(str_buf);
                        }
                    else if (key != LV_KEY_STAR) {
                        extern uint8_t get_family_number_status(uint8_t index,char * number);
                        char            number[20];

                        uint8_t         ret = get_family_number_status(key - LV_KEY_0,number);

                        if (ret <= 1) {
                            screen_remind_param_t screen_remind_param;
                            lv_obj_t *      ui_screen;

                            ui_screen_remind_param_init(&screen_remind_param);
                            screen_remind_param.str = "亲情功能未打开";

                            if (ret == 1) {
                                screen_remind_param.str = "此键亲情号未使用";
                                }

                            screen_remind_param.tiemr_delay = 2000;
                            screen_remind_param.fun =
                                 (remind_timer_callback_fun_t) remind_timer_callback_screen_idle1;
                            screen_remind_param.user_data = ui_Screen;

                            screen_remind_param.new_win = 0;
                            ui_screen           = ui_screen_remind_init(&screen_remind_param);

                            lv_disp_load_scr(ui_screen);
                            }
                        else {
#ifdef CONFIG_APP_CALL_FP
                            {
                                call_dial_number(number,NULL);
                                }
#endif
                            }
                        }


                    key_update_release(key,LV_EVENT_RELEASED);
                    }
                else if ((1 << LV_EVENT_RELEASED) &flag) {
                    idle_num_wirte_ui_enter_param_t enter_param;

                    key_update_release(key,LV_EVENT_RELEASED);
                    memset(&enter_param,0,sizeof(idle_num_wirte_ui_enter_param_t));

                    if ((key >= LV_KEY_0) && (key <= LV_KEY_9)) {
                        enter_param.number[0] = '0' + key - LV_KEY_0;
                        }
                    else if (key == LV_KEY_STAR) {
                        extern void reset_key_star(void);

                        enter_param.number[0] = '*';
                        reset_key_star();
                        }
                    else if (key == LV_KEY_HASH) {
                        enter_param.number[0] = '#';
                        }
                    else {
                        break;
                        }

                    alv_am_win_enter(NULL,"idle_num_write",&enter_param);

                    }
                }
            break;

        default:
            break;
        }

    if (code == LV_EVENT_RELEASED) {
        p_screen_param->key_pressed_in_this_win = 0;
        key_update_release(key,LV_EVENT_RELEASED);
        }

}



